use super::{Root, root_document};

const HEADER: &str =
    "# generated by lablith gen from .lablith; do not edit\n---\n";

const WORKFLOW: &str = "# One pipeline per change (src/pipeline:V10): merge \
    requests, the default\n# branch, tags, schedules and manual runs. A \
    push to a merge request's\n# branch runs its merge request pipeline \
    only.\nworkflow:\n  rules:\n    - if: '$CI_PIPELINE_SOURCE == \
    \"merge_request_event\"'\n    - if: $CI_COMMIT_BRANCH == \
    $CI_DEFAULT_BRANCH\n    - if: $CI_COMMIT_TAG\n    - if: \
    '$CI_PIPELINE_SOURCE == \"schedule\"'\n    - if: '$CI_PIPELINE_SOURCE \
    == \"web\"'\n\nstages: [gate, build, verify, bump]\n";

#[test]
fn the_root_lists_rules_stages_and_local_includes_only() {
    let root = Root {
        includes: vec![
            ".gitlab/ci/ci.yml".into(),
            ".gitlab/ci/hand.yml".into(),
        ],
    };
    let want = format!(
        "{HEADER}{WORKFLOW}\ninclude:\n  - local: '.gitlab/ci/ci.yml'\n  - \
         local: '.gitlab/ci/hand.yml'\n"
    );
    assert_eq!(root_document(&root), want);
}

#[test]
fn a_root_with_nothing_to_include_leaves_include_out() {
    let want = format!("{HEADER}{WORKFLOW}");
    assert_eq!(root_document(&Root::default()), want);
}
